package com.bank.orders;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MinStackDemo {

    private static final Logger log = Logger.getLogger(MinStackDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MinStack stack = new MinStack();

        stack.push(50000L);                 // pending order amounts in rupees
        stack.push(30000L);
        stack.push(80000L);
        log.info(() -> "top=" + stack.top() + " min=" + stack.getMin());  // top 80000, min 30000

        stack.push(20000L);
        log.info(() -> "after push 20000 min=" + stack.getMin());         // min 20000

        stack.pop();                        // removes 20000
        log.info(() -> "after pop min=" + stack.getMin());                // min back to 30000

        stack.pop();                        // removes 80000
        stack.pop();                        // removes 30000
        log.info(() -> "after more pops min=" + stack.getMin());          // min 50000
    }
}

