class MinStack {

    private static final Logger log = Logger.getLogger(MinStack.class.getName());

    private final Deque<Long> main = new ArrayDeque<>();
    private final Deque<Long> mins = new ArrayDeque<>();   // top is always current minimum

    // O(1): push value and mirror the running minimum.
    void push(long value) {
        main.push(value);
        long newMin = mins.isEmpty() ? value : Math.min(value, mins.peek());
        mins.push(newMin);
        log.fine(() -> "push " + value + " -> min " + newMin);
    }

    // O(1): pop both stacks in lockstep.
    long pop() {
        if (main.isEmpty()) {
            throw new IllegalStateException("stack is empty");
        }
        mins.pop();
        long value = main.pop();
        log.fine(() -> "pop " + value);
        return value;
    }

    // O(1): current top value.
    long top() {
        if (main.isEmpty()) {
            throw new IllegalStateException("stack is empty");
        }
        return main.peek();
    }

    // O(1): current minimum value.
    long getMin() {
        if (mins.isEmpty()) {
            throw new IllegalStateException("stack is empty");
        }
        return mins.peek();
    }
}

